mapper.select:
select count(*) from sample_file


		and subbarcode =#{subbarcode}


		and disease_type =#{disease_type}

select sample_id,person_id,person_name,age,
	gender,birthday,patient_id,hospital,received_date,barcode,subbarcode,specimen_type,specimen_quantity,testing_program,disease_type,
	comparison,client,commission_date,sales_contact,report_receiver,collect_date,data_path,info_officer,sample_nature,selected_genes,
	testing_before_medicine,other_description,loaded_date,clinicalremark,cancertype,pathologicaltype,remark,product_name,clinicalstages,
	libraryname,doctorname,fastcode,locationname,report_upload_date,sample_source,from_organ,turmor_cell_ratio,
	gene_type,gene_result,medication_history,birthplace,family_history
from sample_file


		and subbarcode =#{subbarcode}


		and disease_type =#{disease_type}


limit #{pageNo},#{pageSize}
